import{_ as e,o as t,c as r,a5 as o}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ29 字符串加解密","description":"中等 通过率：24.87% 时间限制：1秒 空间限制：32M 描述 对输入的字符串进行加解密，并输出。 加密方法为： 当内容是英文字母时则用该英文字母的后一个字母替换，同时字母变换大小写,如字母a时则替换为B；字母Z时则替换为a； 当内容是数字时则把该数字加1，如0替换1，1替换。","frontmatter":{"title":"HJ29 字符串加解密","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：24.87% 时间限制：1秒 空间限制：32M 描述 对输入的字符串进行加解密，并输出。 加密方法为： 当内容是英文字母时则用该英文字母的后一个字母替换，同时字母变换大小写,如字母a时则替换为B；字母Z时则替换为a； 当内容是数字时则把该数字加1，如0替换1，1替换。","sidebarWeight":98,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/多细节（中等）/HJ29 字符串加解密.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/多细节（中等）/HJ29 字符串加解密.md","filePath":"posts/前端面试与实战/03-算法训练/多细节（中等）/HJ29 字符串加解密.md"}'),i={name:"posts/前端面试与实战/03-算法训练/多细节（中等）/HJ29 字符串加解密.md"};function l(h,a,s,d,n,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<div><h1 id="hj29-字符串加解密" tabindex="-1">HJ29 字符串加解密 <a class="header-anchor" href="#hj29-字符串加解密" aria-label="Permalink to &quot;HJ29 字符串加解密&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ29 字符串加解密”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：24.87% 时间限制：1秒 空间限制：32M <strong>描述</strong> 对输入的字符串进行加解密，并输出。 加密方法为： 当内容是英文字母时则用该英文字母的后一个字母替换，同时字母变换大小写,如字母a时则替换为B；字母Z时则替换为a；</p></blockquote><p>当内容是数字时则把该数字加1，如0替换1，1替换2，9替换0； 其他字符不做变化。</p><p>解密方法为加密的逆过程。 数据范围：输入的两个字符串长度满足 1≤<em>n</em>≤1000 ，保证输入的字符串都是只由大小写字母或者数字组成 <strong>输入描述：</strong> 第一行输入一串要加密的密码 第二行输入一串加过密的密码 <strong>输出描述：</strong> 第一行输出加密后的字符 第二行输出解密后的字符 <strong>示例1</strong> 输入： abcdefgBCDEFGH ==复制== 输出： BCDEFGHabcdefg</p><p>要实现这个加密和解密过程，我们可以定义两个函数：一个用于加密，另一个用于解密。这两个函数会根据提供的规则，对输入的字符串进行相应的字符替换。</p><h3 id="加密规则" tabindex="-1">加密规则： <a class="header-anchor" href="#加密规则" aria-label="Permalink to &quot;加密规则：&quot;">​</a></h3><ul><li>英文字母替换为其后一个字母，并转换大小写。</li><li>数字加1，9替换为0。</li><li>其他字符不变。</li></ul><h3 id="解密规则" tabindex="-1">解密规则： <a class="header-anchor" href="#解密规则" aria-label="Permalink to &quot;解密规则：&quot;">​</a></h3><ul><li>与加密规则相反。</li></ul><p>下面是Python代码实现： def encrypt(text): result = &quot;&quot; for char in text: if char.isalpha():</p><h1 id="英文字母替换为其后一个字母-并转换大小写" tabindex="-1">英文字母替换为其后一个字母，并转换大小写 <a class="header-anchor" href="#英文字母替换为其后一个字母-并转换大小写" aria-label="Permalink to &quot;英文字母替换为其后一个字母，并转换大小写&quot;">​</a></h1><p>if char.islower(): result += chr((ord(char) - ord(&#39;a&#39;) + 1) % 26 + ord(&#39;A&#39;)) else: result += chr((ord(char) - ord(&#39;A&#39;) + 1) % 26 + ord(&#39;a&#39;)) elif char.isdigit():</p><h1 id="数字加1-9替换为0" tabindex="-1">数字加1，9替换为0 <a class="header-anchor" href="#数字加1-9替换为0" aria-label="Permalink to &quot;数字加1，9替换为0&quot;">​</a></h1><p>result += str((int(char) + 1) % 10) else:</p><h1 id="其他字符不变" tabindex="-1">其他字符不变 <a class="header-anchor" href="#其他字符不变" aria-label="Permalink to &quot;其他字符不变&quot;">​</a></h1><p>result += char return result</p><p>def decrypt(text): result = &quot;&quot; for char in text: if char.isalpha():</p><h1 id="逆向替换英文字母-并转换大小写" tabindex="-1">逆向替换英文字母，并转换大小写 <a class="header-anchor" href="#逆向替换英文字母-并转换大小写" aria-label="Permalink to &quot;逆向替换英文字母，并转换大小写&quot;">​</a></h1><p>if char.islower(): result += chr((ord(char) - ord(&#39;a&#39;) - 1) % 26 + ord(&#39;A&#39;)) else: result += chr((ord(char) - ord(&#39;A&#39;) - 1) % 26 + ord(&#39;a&#39;)) elif char.isdigit():</p><h1 id="数字减1-0替换为9" tabindex="-1">数字减1，0替换为9 <a class="header-anchor" href="#数字减1-0替换为9" aria-label="Permalink to &quot;数字减1，0替换为9&quot;">​</a></h1><p>result += str((int(char) - 1) % 10) else:</p><h1 id="其他字符不变-1" tabindex="-1">其他字符不变 <a class="header-anchor" href="#其他字符不变-1" aria-label="Permalink to &quot;其他字符不变&quot;">​</a></h1><p>result += char return result</p><h1 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>text_to_encrypt = input() text_to_decrypt = input()</p><h1 id="加密和解密" tabindex="-1">加密和解密 <a class="header-anchor" href="#加密和解密" aria-label="Permalink to &quot;加密和解密&quot;">​</a></h1><p>encrypted_text = encrypt(text_to_encrypt) decrypted_text = decrypt(text_to_decrypt)</p><h1 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h1><p>print(encrypted_text) print(decrypted_text) 这段代码首先定义了加密和解密函数。在加密函数中，它遍历输入的每个字符，根据字符的类型（字母、数字、其他）应用相应的转换规则，并构建加密后的字符串。解密函数以相同的方式工作，但应用逆向转换规则。最后，代码读取要加密的文本和要解密的文本，调用这些函数，并输出结果。</p></div>',1)])])}const _=e(i,[["render",l]]);export{u as __pageData,_ as default};
